// Package apispec embeds the bundled OpenAPI documents (generated by `redocly bundle`, committed, drift-checked).
// It is a separate package because go:embed cannot reach a parent directory and a package named api is banned.
package apispec

import _ "embed"

//go:embed openapi.bundled.yaml
var public string

//go:embed openapi.admin.bundled.yaml
var admin string

// Public is the document served by the public listener at /api/v1/openapi.yaml and used by its validator.
func Public() []byte { return []byte(public) }

// Admin is the public document plus the admin-only operations (admin listener).
func Admin() []byte { return []byte(admin) }
